function dpUnder(sc){const n=T;/* hall of doors: a long sterile runner */rect(TX(63)+4,TX(33),24,TX(20),'rgba(255,255,255,.04)');
 /* depot: painted lanes */for(let k=0;k<6;k++)rect(TX(31)+k*44,TX(11)+8,30,2,'rgba(242,210,74,.4)');
 /* work room: tape outline of a desk plan (not a body) */c.strokeStyle='rgba(208,40,63,.25)';c.strokeRect(TX(39)+.5,TX(35)+.5,TX(4),TX(2));
 /* dome: water reflections of the hanging flowers */if(sc.zone&&sc.zone.id==='dp_dome')dpDomeReflect(sc)}
function dpOver(sc){if(sc.zone&&sc.zone.id==='dp_dome'){const r=DR.dome;c.save();c.beginPath();c.rect(TX(r[0]),TX(r[1])-6,TX(r[2]-r[0]+1),TX(r[3]-r[1]+1)+6);c.clip();dpDomeFlowers(sc);c.restore()}}
/* ---------- the flower room ---------- */
const DOME=(()=>{const r=DR.dome,L=[];const rnd=mulberry(41);for(let x=r[0]*16+6;x<r[2]*16+12;x+=12)for(let y=r[1]*16+8;y<r[3]*16+12;y+=11){L.push({x:x+(rnd()-.5)*5,y:y+(rnd()-.5)*5,c:['#ff8ab0','#f4f0ea','#c8a0f0','#ffb0c8','#a0d8ff','#f2a0b8'][Math.floor(rnd()*6)],s:.6+rnd()*.8,p:rnd()*6.28,lift:0})}return L})();
function dpDomeFlowers(sc){const p=sc.p,t=T/60;DOME.forEach(f=>{const d=Math.hypot(f.x-p.x,(f.y-p.y+10)*1.2);const want=d<56?1:0;f.lift+=(want-f.lift)*.06;const a=(1-f.lift*.85)*(.75+.25*Math.sin(t+f.p));const yy=f.y-f.lift*16;
  c.globalAlpha=a*.85;c.fillStyle=f.c;c.beginPath();c.arc(f.x,yy,2.2*f.s,0,7);c.fill();c.fillStyle='rgba(255,255,255,.6)';c.fillRect(f.x-.5,yy-.5,1,1);c.globalAlpha=a*.35;rect(f.x-.25,yy-8*f.s,.5,8*f.s,'#6a8a6a')});c.globalAlpha=1}
function dpDomeReflect(sc){const p=sc.p;DOME.forEach(f=>{const a=(1-f.lift*.85)*.22;if(a<=0)return;c.globalAlpha=a;c.fillStyle=f.c;c.fillRect(f.x-1,f.y+10+Math.sin(T/30+f.p),2,3)});c.globalAlpha=1;
 if(sc.zone&&sc.zone.id==='dp_dome'){c.globalAlpha=.35;tdActor(tdWho(),p.x,p.y+30,p.dir==='u'?'d':p.dir==='d'?'u':p.dir,false,0,{});c.globalAlpha=1}}
