dp({id:'dp_kit',x:TX(41),y:TX(10)-2,w:22,d:12,h:10,label:()=>qst('dp_restock')===1?'Fresh cleaning kit (take one)':'Cleaning kits',draw:(x,y)=>{tdBox(x,y,22,12,10,'#d8dce0','#b8bcc0');rect(x+3,y-8,7,5,'#2a6aaa');rect(x+12,y-8,7,5,'#2a6aaa')},
 act:()=>{if(qst('dp_restock')===1){qAdv('dp_restock');tdSay([['','You take a sealed kit off the stack. Gloves, sheeting, the plain-label bottles, the boring things that keep you out of prison.'],[tdN(),dpV()?'The boring things are most of the job. People assume it is the other part.':'boring things. gloves. sheets. the stuff nobody puts in movies. the stuff that actually matters.']])}else dpSay('Stacked by expiry date. The oldest at the front. Rotation is discipline.','sealed kits. stacked by expiry date. he rotates his crime supplies like milk.')}});
dp({id:'dp_jack',x:TX(37),y:TX(10)-2,w:20,d:10,h:6,label:'Pallet jack',seat:tdSeat(TX(37)+10,TX(10)+10,'d'),draw:(x,y)=>{rect(x,y+2,20,3,'#e0a020');rect(x+16,y-14,2,18,'#e0a020');rect(x+12,y-16,10,3,'#2a2a30')},act:(who,L,P,sc)=>{tdSit(sc,P,[['',who==='v'?'He sits on the pallet jack. It rolls one centimetre. He does not move again.':'you sit on the pallet jack. you scoot. you scoot again. this is the best thing in the basement so far.']])}});
/* gallery */
for(let k=0;k<6;k++)dp({id:'dp_case'+k,wall:1,x:TX(31)+k*72+8,y:TX(20),w:56,d:32,label:['Case: expedition gear','Case: the first mask','Case: forty-one keys','Case: maps','Case: the dog collars','Case: an empty case'][k],draw:(x,y)=>dpCase(x,y,k),act:who=>dpCaseLook(k,who)});
dp({id:'dp_globe',x:TX(54),y:TX(23),w:20,d:16,h:20,label:'A big brass globe',draw:(x,y)=>{rect(x+9,y-2,2,10,'#8a6a40');rect(x+3,y+8,14,3,'#6a4e2a');c.fillStyle='#2a4a6a';c.beginPath();c.arc(x+10,y-10,9,0,7);c.fill();c.fillStyle='#4a7a4a';const a=(tdF('curioOpen')?1.2:0)+T/400;c.fillRect(x+6+Math.sin(a)*4,y-14,5,4);c.fillRect(x+9+Math.cos(a)*3,y-8,4,3);c.strokeStyle='#c9a050';c.beginPath();c.arc(x+10,y-10,10,0,7);c.stroke()},act:who=>dpGlobe(who)});
dp({id:'dp_plaque',wall:1,x:TX(54),y:TX(20),w:24,d:32,label:'Brass plaque',draw:(x,y)=>{rect(x+2,y+12,20,10,'#c9a050');rect(x+4,y+15,16,1,'#6a4e2a');rect(x+4,y+18,12,1,'#6a4e2a')},act:()=>tdSay([['','A brass plaque by the globe, engraved: “WHERE THE MONEY NEVER CLEARS.”'],[tdN(),dpV()?'My little joke. I have exactly one.':'a riddle. on a plaque. by a globe. ok, nerd. where does the money never clear.']])});
dp({id:'dp_maptable',x:TX(38),y:TX(23)+8,w:56,d:22,h:10,label:'Map table',draw:(x,y)=>{tdBox(x,y,56,22,10,'#5a4030','#3a2a1e');rect(x+3,y-8,50,18,'#e8dcc0');for(let k=0;k<41;k++)rect(x+5+((k*37)%46),y-6+((k*53)%14),1,1,k%7===0?'#d0283f':'#2a6aaa')},act:()=>tdSay([['','A map of forty-one cities under glass. Blue pins: the foundation’s charities. Red pins: men. Some red pins have been pulled out and laid on their sides, like they’re asleep.'],[tdN(),dpV()?'Sideways means finished. On paper, or otherwise.':'the sideways pins are the finished ones. there are more sideways pins than i thought. there are fewer than he wants.']])});
dp({id:'dp_chair',x:TX(47),y:TX(23)+6,w:20,d:16,h:12,label:'Reading chair',seat:tdSeat(TX(47)+10,TX(24)+12,'d'),draw:(x,y)=>{tdBox(x,y,20,16,12,'#3a4a5a','#2a3a4a');rect(x,y-18,20,8,'#2a3a4a');rect(x+22,y-6,6,6,'#5a4030');rect(x+23,y-12,4,6,'#f4f0ea')},act:(who,L,P,sc)=>tdSit(sc,P,[['',who==='v'?'He sits. On the side table, his reading list for the year. He has crossed out four of the books and written “later” next to them.':'his reading chair. a notepad on the side table: BOOKS SHE MENTIONED. a list. with my books on it. he’s READING them.']])});
/* curio vault */
dp({id:'dp_doll',x:TX(62),y:TX(22),w:14,d:10,h:18,label:'A porcelain doll in a bell jar',draw:(x,y)=>{rect(x+1,y-18,12,20,'rgba(200,220,240,.2)');rect(x+4,y-14,6,6,'#f4e8e0');rect(x+3,y-8,8,8,'#6a1e2a')},act:()=>tdSay([['','A porcelain doll in a bell jar. A typed card: “Recovered from the Hollis residence. Facing the wall when found. Facing the wall since. Do not turn.”'],[tdN(),dpV()?'I do not believe in curses. I do not turn it.':'it’s facing the wall. the card says don’t turn it. i’m not turning it. i’m a professional.']])});
dp({id:'dp_chess',x:TX(65),y:TX(22)+2,w:18,d:14,h:8,label:'A chess set',draw:(x,y)=>{tdBox(x,y,18,14,8,'#3a2a1e','#2a1e14');for(let a=0;a<4;a++)for(let b=0;b<3;b++)rect(x+1+a*4,y-6+b*4,4,4,(a+b)%2?'#e8dcc8':'#3a2a1e');rect(x+5,y-9,2,4,'#141014')},act:()=>tdSay([['','A chess set from a target’s study. The white king is missing. The game on the board is mid-play. Black is winning.'],[tdN(),dpV()?'He was playing himself when I arrived. I left the board exactly as it was. I took the king.':'he took the king. of course he took the king. this man is a walking metaphor.']])});
dp({id:'dp_musicbox',x:TX(68),y:TX(22)+4,w:12,d:10,h:6,label:'Music box',draw:(x,y)=>{tdBox(x,y,12,10,6,'#c9a050','#a8803a');rect(x+2,y-5,8,1,'#6a4e2a')},act:()=>{sfx('chime');tdSay([['','You wind it. It plays a lullaby, backwards. You can just about tell which one.'],[tdN(),dpV()?'It came from the Pike estate. It was like that when I found it. I have never had it fixed. Some things should stay strange.':'it plays backwards. i hummed along. backwards. i’m a natural.']])}});
dp({id:'dp_letter',x:TX(62),y:TX(26),w:14,d:10,h:4,label:'A sealed envelope',draw:(x,y)=>{rect(x+1,y-2,12,8,'#f4f0ea');rect(x+5,y,4,3,'#c2253a')},act:who=>{if(who==='v')return tdSay([['K9','To be opened if I do not come back. It is addressed to her. I rewrite it every month.']]);tdSay([['','A sealed envelope. On the front, in his handwriting: “M. — If I do not come back.” The seal is unbroken.'],['hitmeuppp','no.'],['','You put it back exactly where it was. You intend never to open it.']],()=>tdSetF('sawLetter'))}});
dp({id:'dp_postcard',wall:1,x:TX(65),y:TX(19),w:22,d:32,label:'Postcards pinned to a cork strip',draw:(x,y)=>{for(let k=0;k<3;k++){rect(x+2+k*7,y+10+(k%2)*3,6,8,['#f2d24a','#e8dcc8','#a0d8ff'][k]);rect(x+2+k*7,y+10+(k%2)*3,6,2,'rgba(40,20,10,.5)')}},
 act:()=>tdSay([['','Postcards from Marseille, every one scorched at the corners. The latest, in looping handwriting: “the bakery is fine. MOSTLY. bisous — F.”'],[tdN(),dpV()?'Felicie writes after every fire, as a professional courtesy. I keep them down here, away from the paper archive. Also as a professional courtesy.':'felicie! she burns something and then sends a postcard about it. “mostly.” the bakery is NOT fine. the bakery is gone.']])});
dp({id:'dp_photo',x:TX(68),y:TX(26),w:14,d:8,h:10,label:'A framed photo, face down',draw:(x,y)=>{rect(x,y-2,14,6,'#3a2a1e')},act:()=>tdSay([['','You turn it over. A beach party at sunset. A tall man with a cat in one arm and a girl on his back, both of them laughing so hard the photo is blurry.'],['','On the back: “Vince & Ai Hua. Do NOT put this in a file. — A.H.”'],[tdN(),dpV()?'I was told not to put it in a file. So it is in a frame. Face down. Professional courtesy, with the Sunset Slasher, is complicated.':'ai hua sent him this?? vince is holding a CAT. the sunset slasher. holding a cat. so normal it’s terrifying.']])});
dp({id:'dp_tunmap',x:TX(66),y:TX(28)-2,w:20,d:10,h:6,label:()=>tdF('tunnelMap')?'Survey drawings':'Rolled-up survey drawings',draw:(x,y)=>{rect(x,y-2,20,6,'#e8dcc8');rect(x,y-2,20,1,'#c8bca8');rect(x+16,y-3,4,8,'#c2253a')},act:who=>{if(tdF('tunnelMap'))return dpSay('The tunnel comes out in the forest above the river. It was a service drain once. Now it is the only way out of this house I have not told the architect about.','the tunnel goes to the forest. i memorised it. i memorise all exits. it’s a whole thing.');tdSetF('tunnelMap');toast('The service tunnel hatch can be opened now');tdSay([['','Survey drawings of the house. Every level. And one more line, drawn in red pencil, from the hall of doors to the edge of the property: SERVICE TUNNEL → FOREST.'],[tdN(),who==='v'?'The way out nobody else knows about.':'a back door to the forest. he has a BACK DOOR TO THE FOREST. ok. ok i’m going.']])}});
dp({id:'dp_b4key',x:TX(69),y:TX(28)-2,w:10,d:8,h:6,show:()=>!tdF('b4key'),label:'A small key on a ribbon',draw:(x,y)=>{rect(x+2,y-2,6,3,'#b8b8c0');rect(x,y-4,3,6,'#c2253a')},act:()=>{tdSetF('b4key');sfx('chime');toast('Got: B4 key');tdSay([['','A small steel key on a red ribbon, in a dish labelled B4 in V’s capitals. Next to it, a note: “If you found this, you found the globe. Fine. Go down.”']])}});
/* cinema */
dp({id:'dp_screen',wall:1,x:TX(10),y:TX(27),w:TX(10),d:32,label:'The screen',draw:(x,y)=>{rect(x,y+2,TX(10),28,'#141014');const on=TDP.film>T;rect(x+4,y+4,TX(10)-8,22,on?['#3a5a8a','#8a3a3a','#e8dcc0','#2a2a2a','#5a3a6a'][Math.floor(T/40)%5]:'#e8e4dc');if(on)for(let k=0;k<6;k++)rect(x+4,y+4+((T*3+k*23)%22),TX(10)-8,1,'rgba(0,0,0,.2)');rect(x,y+2,6,28,'#6a1e2a');rect(x+TX(10)-6,y+2,6,28,'#6a1e2a')},act:who=>dpFilm(who)});
for(let r=0;r<3;r++)dp({id:'dp_seats'+r,x:TX(10),y:TX(33)+r*28,w:TX(10),d:12,h:12,label:'Cinema seats',seat:tdSeat(TX(15),TX(34)+r*28,'u'),draw:(x,y)=>{for(let k=0;k<8;k++){tdBox(x+k*20,y,18,12,10,'#7a1e2a','#5a121e','#9a2a3a');rect(x+k*20,y-14,18,6,'#5a121e')}},act:(who,L,P,sc)=>{tdSit(sc,P,[['',TDP.film>T?(who==='v'?'He sits in the middle of the row. He always sits in the middle of the row.':'you slump into a seat. it is the softest thing you have ever sat on and you have sat on V.'):(who==='v'?'An empty cinema. He sits anyway. The silence is very expensive.':'empty cinema. velvet. a cupholder the size of your head. you could live here.')]])}});
dp({id:'dp_popcorn',x:TX(9),y:TX(30),w:18,d:14,h:26,label:'Popcorn machine',draw:(x,y)=>{tdBox(x,y,18,14,8,'#c2253a','#8a1a2a');rect(x+2,y-24,14,16,'rgba(255,250,220,.4)');for(let k=0;k<6;k++)rect(x+3+(k*5)%12,y-12-(k%3)*3,2,2,'#fff4c0');rect(x+2,y-26,14,2,'#c2253a')},act:()=>{apply({energy:4});dpSay('I clean it after every use. It has been used once.','free popcorn. in a secret cinema. in a secret basement. i’m never leaving.')}});
dp({id:'dp_reels',x:TX(20),y:TX(30),w:20,d:12,h:28,label:'Film shelf',draw:(x,y)=>{tdBox(x,y,20,12,28,'#3a2a1e','#2a1e14');for(let k=0;k<4;k++)for(let j=0;j<2;j++){c.fillStyle=['#8a8a92','#c9a050','#c2253a'][(k+j)%3];c.beginPath();c.arc(x+5+j*10,y-22+k*6,3,0,7);c.fill()}},act:()=>tdSay([['','Film cans and DVD cases. HEATHERS (Ronin’s, “on loan”). CARRIE 1976 (Angel’s, “a gift, keep it, i have three”). A box set with a sticky note: “Vince — lent, never returned.”'],[tdN(),dpV()?'Vince borrowed the projector manual and returned a box set. Ai Hua says that is how he apologises.':'vince left his box set here. ai hua says he cried at the end of every single one. the sunset slasher. cries at movies. i love this server.']])});
dp({id:'dp_booth',x:TX(14),y:TX(39)+2,w:28,d:12,h:16,label:'Projector booth',draw:(x,y)=>{tdBox(x,y,28,12,16,'#2a2a30','#1e1e24');rect(x+10,y-12,8,6,'#5a5a62');if(TDP.film>T){c.fillStyle='rgba(220,230,255,.25)';c.beginPath();c.moveTo(x+14,y-10);c.lineTo(x-30,y-140);c.lineTo(x+60,y-140);c.fill()}},act:who=>dpFilm(who)});
