dp({id:'dp_wc2sink',x:TX(30)+2,y:TX(30)+2,w:30,d:12,h:12,label:'Sink',draw:(x,y)=>{tdBox(x,y,30,12,12,'#f4f4ee','#d8d8d0');rect(x+8,y-10,12,5,'#c8d0d4')},act:()=>dpSay('The west washroom. The water here comes from a different tank. It tastes of nothing. That is the point of it.','water. tastes like nothing. like a hospital’s idea of water.')});
dp({id:'dp_mirror2',x:TX(35),y:TX(30),w:14,d:22,h:30,solid:false,label:()=>tdF('mirrorOpen')?'The mirror (it swings)':'A full-length mirror',draw:(x,y)=>{rect(x,y-26,14,46,'#5a6066');rect(x+2,y-24,10,42,tdF('mirrorOpen')?'#2a3038':'#8a96a0');rect(x+3,y-22,2,30,'rgba(255,255,255,.3)')},act:who=>dpMirror(who)});
/* the work room */
dp({id:'dp_rules',wall:1,x:TX(39),y:TX(27),w:40,d:32,label:'THE RULES',draw:(x,y)=>{rect(x+2,y+4,36,24,'#f4f0ea');txt('THE RULES',x+20,y+10,'#c2253a',5,'center');for(let k=0;k<5;k++)rect(x+5,y+13+k*3,26-(k%2)*6,1,k===3?'#ff6fa8':'#3a3a42')},act:who=>dpRules(who)});
dp({id:'dp_namesboard',wall:1,x:TX(43),y:TX(27),w:52,d:32,label:'The board',draw:(x,y)=>{rect(x+2,y+3,48,26,'#8a6a40');for(let k=0;k<8;k++){rect(x+4+(k%4)*12,y+5+Math.floor(k/4)*12,9,10,'#e8e0d0');if((S&&S.f&&S.f['done_'+(TARGETS[k]||{}).id]))rect(x+4+(k%4)*12,y+9+Math.floor(k/4)*12,9,1,'#c2253a')}},act:who=>dpBoard(who)});
dp({id:'dp_burners',x:TX(39),y:TX(31),w:26,d:14,h:12,label:'Burner drawer',draw:(x,y)=>{tdBox(x,y,26,14,12,'#5a6066','#3a4046');for(let k=0;k<4;k++)rect(x+3+k*6,y-10,4,6,'#141418')},act:who=>dpBurners(who)});
dp({id:'dp_station',x:TX(46),y:TX(30),w:30,d:14,h:14,label:'Cleaning station',draw:(x,y)=>{tdBox(x,y,30,14,14,'#d8dce0','#b8bcc0');rect(x+3,y-12,6,8,qst('dp_restock')>=3||qst('dp_restock')<0?'#2a6aaa':'#5a6066');rect(x+12,y-12,14,6,'#f4f0ea')},act:who=>dpStation(who)});
dp({id:'dp_safe',x:TX(47),y:TX(34),w:20,d:16,h:20,label:'Cash safe',draw:(x,y)=>{tdBox(x,y,20,16,20,'#3a3e46','#2a2e36','#5a5e66');c.strokeStyle='#c9a050';c.beginPath();c.arc(x+10,y-6,4,0,7);c.stroke()},act:who=>dpSafe(who)});
dp({id:'dp_furnace',x:TX(39),y:TX(35),w:28,d:18,h:26,label:'The furnace',draw:(x,y)=>{tdBox(x,y,28,18,26,'#3a2a24','#2a1e1a','#5a4038');const on=TDP.burn>T;rect(x+8,y-4,12,10,on?['#ff6a2a','#ffb04a','#ff8a3a'][(T>>3)%3]:'#1a1210')},light:()=>TDP.burn>T?{dx:14,dy:4,r:60,i:.9,col:'255,140,60',flick:.4}:null,act:who=>dpFurnace(who)});
dp({id:'dp_calendar',wall:1,x:TX(46)+8,y:TX(27),w:24,d:32,label:'Alibi calendar',draw:(x,y)=>{rect(x+2,y+6,20,20,'#f4f0ea');for(let k=0;k<12;k++)rect(x+4+(k%4)*4,y+10+Math.floor(k/4)*5,3,3,k%5===0?'#c2253a':'#d8d0c8')},act:who=>dpCalendar(who)});
dp({id:'dp_plan',x:TX(42),y:TX(32)+4,w:36,d:22,h:10,label:'Planning table',draw:(x,y)=>{tdBox(x,y,36,22,10,'#4a4e56','#3a3e46');rect(x+3,y-8,30,18,'#2a4a3a');for(let k=0;k<9;k++)rect(x+5+(k*11)%26,y-6+(k*7)%14,2,2,k%3?'#f2d24a':'#d0283f');c.strokeStyle='rgba(242,210,74,.5)';c.beginPath();c.moveTo(x+6,y-4);c.lineTo(x+18,y+2);c.lineTo(x+28,y-6);c.stroke()},act:who=>dpPlan(who)});
/* B4 corridor & false exits */
dp({id:'dp_emerg',wall:1,x:TX(33),y:TX(41),w:32,d:32,label:'EMERGENCY EXIT',draw:(x,y)=>{rect(x+2,y+4,28,28,'#3a3e46');for(let k=0;k<7;k++)rect(x+2+k*4,y+4,2,3,k%2?'#141418':'#f2d24a');rect(x+6,y+10,20,20,'#5a5e66');rect(x+8,y+18,16,2,'#c9c39a');txt('EXIT',x+16,y+3,'#7fe08a',6,'center')},
 act:()=>{tdMark('fakeExit');tdSay([['','You push the bar. The door opens onto a brick wall, so close you could lick it. Somebody has spray-painted a small smiley face on the bricks.'],[tdN(),dpV()?'Every intruder who has read a building code runs for the green sign. It is a very good sign. I chose the green myself.':'FAKE. it’s FAKE. he painted a smiley face on the brick. for the people who die here, probably. RUDE.']])}});
dp({id:'dp_manhole',wall:1,x:TX(50),y:TX(16),w:20,d:32,label:'Ladder up (a manhole)',draw:(x,y)=>{rect(x+3,y-4,2,36,'#8a8e94');rect(x+15,y-4,2,36,'#8a8e94');for(let k=0;k<7;k++)rect(x+3,y-2+k*5,14,1,'#a8acb0');rect(x,y-6,20,4,'#2a2c32')},act:()=>{tdMark('fakeManhole');tdSay([['','You climb. At the top, a manhole cover, welded shut from the inside. A neat bead of weld all the way round. A label: OUT OF ORDER (ON PURPOSE).'],[tdN(),dpV()?'An exit that does not open is still useful. It tells you who panics.':'welded. labelled “on purpose.” this whole house is a personality test and i’m passing.']])}});
dp({id:'dp_b4sign',wall:1,x:TX(28),y:TX(41),w:28,d:32,label:'B4 sign',draw:(x,y)=>{rect(x+2,y+10,24,10,'#2a3038');txt('B4',x+14,y+18,'#d0283f',7,'center')},act:()=>dpSay('Sub-level four. Below the drains. Below anything on any city plan.','B4. deeper than the drains. deeper than the plans. deeper than my feelings (not that deep).')});
/* hall of doors */
const HOD=[['A mop cupboard','A mop, a bucket, a single rubber duck. Nobody has explained the duck.'],['A door to a wall','Another brick wall. This one has a doorbell on it. You press it. It works. Nothing happens.'],['A door to a mirror','The door opens onto a mirror. For a second you think it’s another hallway.'],['Storage: “M.”','A small, dry room. Boxes labelled in his writing: M. — WINTER. M. — SPARE CLIPS. M. — THINGS SHE LEFT AT MY HOUSE BEFORE SHE LIVED HERE. Everything you ever forgot there, folded.'],['A door with no handle','There is no handle. You knock. Somebody, very faintly, knocks back. Then the knocking stops and you decide it was the pipes. It was the pipes.'],['A cupboard of coats','Coats. Black, black, black, and one bright green raincoat with cat ears, which is yours, which you lost two months ago.'],['A door marked “DO NOT”','Behind it: another door marked “I MEAN IT.” Behind that, a broom.']];
HOD.forEach(([n,t],i)=>{const left=i%2===0;const y=TX(34)+i*36;dp({id:'dp_hod'+i,x:left?TX(63)-2:TX(64)+12,y,w:6,d:20,h:20,solid:false,flat:1,label:n,draw:(x,yy)=>{rect(left?x-6:x+2,yy-12,10,26,['#9aa0a6','#8a9096','#a0a6ac'][i%3]);rect(left?x+2:x+2,yy,2,3,'#5fd4c4')},act:who=>{tdMark('hod'+i);tdSay([['',t],i===3?[tdN(),who==='v'?'She left things. I kept them. I did not know yet that I was keeping them for her to find.':'he kept everything. i forgot a sock at his house in week one. it’s here. it’s FOLDED.']:null])}})});
/* tunnel */
dp({id:'dp_tunnelout',x:TX(75),y:TX(55),w:28,d:32,exit:sc=>sc.trans(()=>forestEnter())});
dp({id:'dp_grate',wall:1,x:TX(73),y:TX(53),w:32,d:32,label:'Grate to the forest',draw:(x,y)=>{rect(x+2,y+2,28,30,'#1a1e18');for(let k=0;k<6;k++)rect(x+4+k*4,y+2,1,30,'#5a5e56');c.fillStyle='rgba(120,180,120,.25)';c.fillRect(x+3,y+3,26,8)},act:()=>forestEnter()});
dp({id:'dp_drip',x:TX(68),y:TX(55)+4,w:16,d:10,flat:1,solid:false,label:'A puddle',draw:(x,y)=>{c.fillStyle='rgba(120,150,190,.3)';c.beginPath();c.ellipse(x+8,y+5,8,3,0,0,7);c.fill()},act:()=>dpSay('The tunnel leaks after rain. I like it. It is the only place in the house that does something I did not plan.','puddle. there’s a frog. hi frog. u live in a murder tunnel. same.')});
/* the flower room */
