function dpShelf(x,y,row,seg){rect(x,y-28,60,2,'#8a9096');rect(x,y-28,2,40,'#6a7076');rect(x+58,y-28,2,40,'#6a7076');for(let k=0;k<3;k++){rect(x,y-18+k*10,60,2,'#a8b0b8');for(let b=0;b<4;b++){const col=[['#e8dcc0','#c2253a','#2a6aaa','#f4f0ea'],['#3a5a3a','#c9a050','#e8dcc0','#8a8a92'],['#2a6aaa','#f4f0ea','#d8b878','#c2253a']][row][(b+k+seg)%4];rect(x+3+b*14,y-26+k*10,11,8,col)}}}
function dpShelfLook(row,seg){const L=[['Rice, twenty-kilo sacks. Water in sealed drums. Tinned fish, tinned peaches, tinned everything.','Dog food, in quantities that would feed a small army of very good dogs. One shelf labelled BISCUIT-PROOF. The lids are bent.','Toilet paper, a pallet of it. A single bottle of champagne behind it, hidden. A sticky note: “for after.”'],
 ['Bandages, sutures, saline, the sort of first-aid stock a hospital would be jealous of.','Batteries, torches, radios. Spare parts for things that haven’t broken yet.','Gloves in every size. Shoe covers. Plain overalls. Rows and rows of nothing-coloured clothing.'],
 ['Duct tape. A frankly worrying amount of duct tape.','Blankets, folded military-flat. One of them is knitted, pink and green and lumpy. It has a label: “M. MADE THIS. DO NOT USE. ONLY LOOK.”','Plastic sheeting, rolled. Paper overalls. You know what these are for. You don’t comment. Neither does the shelf.']][row][seg];
 tdSay([['',L],[tdN(),dpV()?pk(['Inventory is a love language. Ask anyone. Ask nobody, actually.','Everything here is for a bad day that I hope never comes.']):pk(['he built a bunker. a cozy bunker. a cozy murder bunker.','if the world ends i’m coming here. i’m bringing the dogs. i’m bringing ronin (maybe).'])]])}
function dpCase(x,y,k){rect(x+2,y+4,52,24,'rgba(170,210,230,.18)');rect(x+2,y+4,52,1,'rgba(255,255,255,.35)');const items=[()=>{rect(x+10,y+14,8,10,'#5a4030');rect(x+22,y+12,14,4,'#8a8a92');rect(x+40,y+14,6,10,'#3a5a3a')},()=>{rect(x+20,y+10,14,12,'#141014');rect(x+22,y+14,4,2,'#c2253a');rect(x+28,y+14,4,2,'#c2253a')},()=>{for(let i=0;i<41;i++)rect(x+5+(i%14)*3,y+8+Math.floor(i/14)*5,1,3,'#c9c39a')},()=>{rect(x+8,y+10,36,14,'#e8dcc0');rect(x+14,y+14,8,6,'#a8c8a0')},()=>{for(let i=0;i<5;i++){c.strokeStyle=['#c2253a','#2a6aaa','#c9a050','#141014','#7fe08a'][i];c.beginPath();c.arc(x+10+i*9,y+16,3,0,7);c.stroke()}},()=>{}];items[k]()}
function dpCaseLook(k,who){const L=[['Expedition gear from a decade ago: a compass, a pick, a field journal swollen with river water. Labels in an old hand: SURVEY, 1987.','My father surveyed this land before he bought it. He never wrote down what he found under it. I did.','his dad’s stuff. old. swollen. V’s labels on top of his dad’s labels. like he’s correcting him.'],
 ['A black cloth mask, crude, stitched by hand. The first K9.','I made it at nineteen from a pair of my school trousers. It did not fit. I wore it for two years anyway.','the first mask. it’s so BAD. it’s stitched with the wrong thread. he wore this. i’m crying (i’m not crying).'],
 ['Forty-one keys on a velvet board, each with a city tag.','One key for each city. Each one opened a door I should not have been behind.','forty-one keys. forty-one cities. forty-one doors. this man collects metaphors like i collect stickers.'],
 ['Maps, hand-drawn: escape routes from forty-one buildings, all in V’s small square hand.','Routes out. I draw the way out before I draw anything else.','escape routes. he draws the exit first. same. i count exits. we’re the same person with different rent.'],
 ['Five dog collars, different colours, each with a tag and a date.','The dogs I could not save in time. I keep them where I walk past them.','five collars. five dates. he walks past them every day. on purpose.'],
 ['An empty glass case with a brass plate and no engraving.','For whatever comes next. I keep one case empty so the gallery is never finished.','empty case. no label. “for whatever comes next.” he’s so dramatic. ...can i be in it. not literally.']][k];
 tdSay([['',L[0]],[tdN(),who==='v'?L[1]:L[2]]])}
function dpGlobe(who){if(tdF('curioOpen'))return dpSay('Lisbon. Where the money never clears.','lisbon. obviously. he complains about lisbon every day.');
 ask(tdN(),'The globe turns on a brass axis. There are three little brass stops you could set it to.',[{t:'Kyoto',fn:()=>dpGlobeTry(0)},{t:'Lisbon',fn:()=>dpGlobeTry(1)},{t:'This city',fn:()=>dpGlobeTry(2)},{t:'Leave it',fn:()=>{}}])}
function dpGlobeTry(n){if(n!==1){sfx('snap');return tdSay([['','The globe clicks into place. Nothing happens. Somewhere, a dog barks (upstairs, unrelated).']])}tdSetF('curioOpen');sfx('chime');TDP.shake=T+30;
 tdSay([['','The globe clicks onto Lisbon. Something heavy unlatches in the east wall of the gallery. A panel swings in.'],[tdN(),dpV()?'Lisbon. Where the money never clears. I am quite proud of that one.':'LISBON. “where the money never clears.” he says “lisbon is late again” every DAY. i KNEW it.']])}
function dpMirror(who){if(tdF('mirrorOpen'))return dpSay('Behind the mirror, the work room.','behind the mirror. the work room. i know the way now.');
 const can=who==='v'||tier()>=2||['after','act2','act3','epilogue'].includes(S.phase);
 if(!can)return tdSay([['','A full-length mirror on a hinge-shaped frame. It’s cold. Colder than glass should be. There’s a draught coming from behind it.'],['hitmeuppp','there’s a room behind this. i can feel the air. i’m not opening it. yet. he’ll show me. ...probably.']]);
 tdSetF('mirrorOpen');tdSay(who==='v'?[['','He presses the corner of the frame. The mirror swings open on silent hinges.'],['K9','The work room. Where the part of my life that is not on paper happens.']]:[['','You press the corner of the frame, where the glass is coldest. The mirror swings open, silent, onto a lit room.'],['hitmeuppp','oh.'],['hitmeuppp','oh, this is where he does it. the actual part. not the charity part.'],['','The air smells of bleach and coffee. Somewhere, a radio is playing very quietly. Everything is labelled.']])}
function dpRules(who){tdSetF('workSeen');qStartSafe('dp_restock');
 tdSay([['','THE RULES, written in two hands on a sheet of printer paper, laminated.'],['','1. No children. 2. No bystanders. 3. Nobody who would be missed by the wrong people. 4. Never on a Tuesday. 5. Eat something.'],['',dpV()?'Rules 4 and 5 are in her handwriting and his, respectively. He has never asked why not Tuesdays.':'rule 4 is yours. rule 5 is his. he has never asked why not tuesdays. you’ve never told him it’s because tuesdays are when the trailer gets the good noodles.'],[tdN(),dpV()?'Without rules it is only killing. I need them. I suspect she needs them less than she should.':'rules. i never had rules before. i had “get paid.” he says that’s not a rule, it’s a weather report.']],()=>{if(!tdF('autonomyHint')&&tier()>=2){tdSetF('autonomyHint');tdThink(dpV()?'She wrote rule four in about two seconds. She has never once hesitated over this work. I want to understand that. I am afraid to.':'he looks at me sometimes like the job should weigh more than it does. it doesn’t. he doesn’t know what the other option was.',360)}})}
function dpBoard(who){const done=TARGETS.filter(t=>S.f['done_'+t.id]).length;tdSay([['','Index cards in two columns. PENDING. FINISHED. '+done+' cards in FINISHED, each crossed with one red line, never two.'],['','At the edge, a separate card in V’s writing: PROFESSIONAL COURTESY. “Sunset Slasher (V.) — beaches west of the river, do not overlap. Felicie — Marseille, anything flammable, do not invite. Luca — do not let him carry anything.”'],[tdN(),dpV()?'Other people do this work. We are the only ones who label things.':'there’s a TERRITORY card. vince gets the beaches. felicie gets “anything flammable.” luca gets “do not let him carry anything.” luca would agree.']])}
function dpBurners(who){const t=tdS();const d=t.f.burnerDay;if(d===S.day)return dpSay('Today’s phone is in my pocket. Tomorrow’s is in the drawer. Yesterday’s is in the furnace.','today’s phone: in my pocket. old one: in the furnace. i used to just. have a phone. like a person.');
 t.f.burnerDay=S.day;save();apply({heat:-3});tdSay([['','A drawer of identical cheap phones, each in its plastic, each with a strip of tape: a date. You swap today’s in, and drop yesterday’s in the furnace tray.'],[tdN(),dpV()?'Routine is how you stay invisible.':'swap. burn. repeat. it’s like flossing. nobody thanks you but your teeth don’t get arrested.']])}
function dpStation(who){const q=qst('dp_restock');if(q<0){qStartSafe('dp_restock');return}
 if(q===0){qAdv('dp_restock');return tdSay([['','The cleaning station. Hooks for gloves, a rack for sealed kits. The rack is empty except for one kit with a red tag: USED.'],[tdN(),dpV()?'Empty. Restock from the depot. Never leave it empty. Empty is how people get caught.':'empty. he’s gonna give me The Look. depot. fresh kit. go.']])}
 if(q===2){qAdv('dp_restock');apply({heat:-12});return tdSay([['','You slot the fresh kit onto the rack and drop the used one in the furnace tray. Everything is where it should be.'],[tdN(),dpV()?'Good. It is the most boring part of the work and the most important. Thank you.':'restocked. the most boring crime chore. V will notice. V notices everything. i want a sticker.']])}
 dpSay('Stocked. Labelled. Boring. Good.','stocked. i stocked it. look at me, logistics.')}
function dpSafe(who){const q=qst('dp_wash');if(dpV()){return tdSay([['','The safe. Cash from her work, waiting to become something else.'],['K9','Her money comes in here as cash and goes out as a donation to a children’s hospital, from a donor who does not exist. Then the hospital hires a contractor who does exist. The contractor is her.'],['K9','I do not tell her how many steps there are. I tell her it is clean.']])}
 if(q<0){qStartSafe('dp_wash');return tdSay([['','A squat steel safe. A note on top in V’s hand: “M. — cash goes in here, please. I know about under the bed. I know about the cactus.”'],['hitmeuppp','how does he know about the cactus.']])}
 if(q===0){qAdv('dp_wash');return tdSay([['','You put the envelope from your last job in the safe. It feels like putting a dog into a kennel. You know it’ll be fine. You still don’t like walking away.'],['hitmeuppp','ok. now what. he said “take it to ops.” i don’t know what “it” is anymore. it’s a number.']])}
 dpSay('','the safe. empty. clean. like it never happened. it’s meant to look like that. it’s still weird.')}
function dpFurnace(who){const q=qst('dp_burn');if(q<0)qStartSafe('dp_burn');
 if(qst('dp_burn')===1){qAdv('dp_burn');TDP.burn=T+600;sfx('snap');return tdSay([['','You feed the bag into the furnace. The door clanks. The fire takes it like it was hungry.'],[tdN(),dpV()?'Clothes, gloves, the last of a bad night. Ronin taught me the temperature. I will not say how he knows.':'gone. the hoodie i liked, too. RIP hoodie. ronin knows the exact temperature. ronin knows too much.']],()=>{qAdv('dp_burn');apply({heat:-10})})}
 TDP.burn=T+120;tdSay([['','The furnace. Steel, brick-lined, older than the house above it. It ticks as it cools.'],[tdN(),dpV()?'My father installed it. He used it for documents. I use it for the same thing, in a broader sense.':'a furnace. in the work room. i’m not even surprised anymore. i’m a little surprised.']])}
function dpCalendar(who){const q=qst('dp_alibi');if(q<0){qStartSafe('dp_alibi');qAdv('dp_alibi');return tdSay([['','A wall calendar. Every day has two lines in tiny writing: where you were, and who saw you there. Tonight is blank.'],[tdN(),dpV()?'Tonight needs a witness. Angel films. Angel always films.':'tonight’s blank. angel. i need angel’s camera and her terrifying commitment to the bit.']])}
 if(q===2){qAdv('dp_alibi');apply({heat:-10});fr('a',3);return tdSay([['','You write it in: STUDIO, ANGEL, 8–11pm, 41 MINUTES OF FOOTAGE, TIMESTAMPED.'],[tdN(),dpV()?'Paper alibis. They hold because everybody in them is real.':'alibi: filed. angel made me do a whole “get ready with me.” it has eleven thousand views. i’m a content creator now.']])}
 dpSay('Every day accounted for. Mine and hers.','every day filled in. i used to just. not have a calendar. i used to just be places.')}
function dpPlan(who){tdSay([['','The planning table. A city map, pins, string, a pencil worn to a nub. Routes in, routes out, a car swap marked with a little drawing of a car.'],['','Sticky notes in two hands. V’s: “Delivery van, 21:40, back alley. Camera dead zone 3m.” Hers: “BRING SNACKS.”'],[tdN(),dpV()?'Planning is ninety percent of it. The rest is being the kind of person who can follow a plan when it goes wrong.':'he plans. i improvise. together we are one (1) competent murderer. and snacks.']])}
function dpFilm(who){if(TDP.film>T)return tdSay([['','The film flickers on. Somewhere in the projector booth something smells pleasantly of hot dust.']]);
 ask(tdN(),'The projector. A shelf of films. A seat with your name on it (not literally. ...it is literally. there’s a little brass plate).',[{t:'Heathers',fn:()=>dpFilmGo('Heathers','Ronin’s favourite. Every line out loud, all the way through.')},{t:'Carrie (1976)',fn:()=>dpFilmGo('Carrie','Angel insists on the 1976 one. The prom scene. Everybody goes quiet.')},{t:'Something with dogs in it',fn:()=>dpFilmGo('a film with dogs in it','Nobody dies. V checked first. V always checks first.')},{t:'The newsreel',fn:()=>dpNews()},{t:'Not now',fn:()=>{}}])}
function dpFilmGo(n,line){TDP.film=T+3600;if(S.dark&&typeof calm==='function')calm(6);apply({energy:-2});const vH=!dpV();tdSay([['','The lights dim. '+n+' fills the screen, ten feet tall.'],['',line],[tdN(),dpV()?'She would laugh at this part. I find myself laughing at it for her.':'perfect. no ads. no phones. no one kicking my seat except my own feet on the seat in front.']])}
function dpNews(){TDP.film=T+900;tdSay([['','The projector plays the evening news, recorded. A presenter: “—no new attacks attributed to the so-called Sunset Slasher since spring. Police sources say the beach killings have stopped. Locals say the man they suspect has been seen walking a cat—”'],[tdN(),dpV()?'He has a girlfriend now. Ai Hua posts photographs. I have asked her not to. She has asked me to mind my business. It is a reasonable request.':'vince got a girlfriend and a CAT and stopped killing people at the beach. character development. ai hua is a genius.']])}
function dpDomeSit(who,P,sc){tdSit(sc,P,null);tdSay(who==='v'?[['','He sits in the middle of the room he built. Thousands of flowers above him, lifting when he moves, settling when he’s still.'],['K9','She said it was the only place she could remember being happy without having to earn it first. I could not take her there. So I brought it here.']]:[['','You sit. The flowers above you lift away, all at once, like a held breath. When you stay still they come back down, close enough to touch.'],['hitmeuppp','i told him once. one time. at four in the morning. that this was the only place i could remember being happy without having to earn it first.'],['hitmeuppp','he built it. under his house. eighteen metres down. i’m not crying. it’s the humidity. the flowers are very humid.']],()=>{apply({aff:2});if(S.dark&&typeof calm==='function')calm(12)})}
