function forestEnter(){go(tdScene('forest',TX(3)+8,TX(22),'r',{banner:1}));setTimeout(()=>{if(scene&&scene.td&&scene.M.id==='forest'&&!dlg&&!ctrl)tdThink(dpV()?'Wind. Pine. The river, somewhere below. Nobody knows this way out but me. And now her.':'trees. stars. the river down there somewhere. ...hey. hey V. bet u can’t catch me.',300)},400)}
/* chase: run from them, or hunt them */
function chaseMenu(){const other=dpV()?'Misaki':'V';tdAsk(dpV()?'The clearing. She is already stretching, which means she has already decided.':'the clearing. he’s right behind you, pretending he isn’t ready.',[{t:'Run — let '+other+' chase you',sub:'reach the torii or last 45 seconds',fn:()=>chaseStart('run')},{t:'Hunt — chase '+other,sub:'catch them within 45 seconds',fn:()=>chaseStart('hunt')}])}
function chaseStart(mode){const sc=scene;if(!sc||!sc.td)return;const o=dpV()?'m':'v';const sx=sc.p.x+(mode==='run'?-90:120),sy=sc.p.y+20;const f=tdFree(sc.M,sx,sy);
 TDP.chase={mode,o,x:f[0],y:f[1],t:0,dur:45*60,stam:100,path:null,pt:0,dir:'r',fr:0,done:false,grace:90};tdSay([['',mode==='run'?(dpV()?'She counts to three, or pretends to. She is already running after you.':'he counts to three, slowly, like a man who has never lost a game in his life. you’re gone by two.'):(dpV()?'You give her a five-second head start. She takes eight.':'he gives you a head start. no he doesn’t. he gives HIMSELF a head start. GO.')],['','(Hold Shift to sprint. Sprinting tires you out.)']])}
function chaseSpeed(sc){const C=TDP.chase;if(!C||C.done)return 1;if(held.alt&&C.stam>0){C.stam=Math.max(0,C.stam-1.1);return 1.5}C.stam=Math.min(100,C.stam+.35);return 1}
function chaseTick(sc){const C=TDP.chase;if(!C||C.done||dlg||ctrl)return;const p=sc.p,M=sc.M;C.t++;if(C.grace>0)C.grace--;
 let tx,ty;if(C.mode==='run'){if(--C.pt<=0||!C.path||!C.path.length){C.pt=24;const pa=tdPathTo(M,C.x,C.y-2,(i,j)=>{const d=Math.hypot(i*TS+8-p.x,j*TS+12-p.y);return d<20?d:null});C.path=pa}}
 else{if(--C.pt<=0||!C.path||!C.path.length){C.pt=40;const pa=tdPathTo(M,C.x,C.y-2,(i,j)=>{const d=Math.hypot(i*TS+8-C.x,j*TS+12-C.y);if(d>TS*6)return null;return 400-Math.hypot(i*TS+8-p.x,j*TS+12-p.y)});C.path=pa}}
 if(C.path&&C.path.length){[tx,ty]=C.path[0];if(Math.hypot(tx-C.x,ty-C.y)<3){C.path.shift()}}
 if(tx!==undefined){const sp=(C.mode==='run'?1.42:1.18)*(C.grace>0?0:1)*(C.mode==='hunt'&&(C.t%180)<20?0:1);const dx=tx-C.x,dy=ty-C.y,dd=Math.hypot(dx,dy)||1;const nx=C.x+dx/dd*sp,ny=C.y+dy/dd*sp;if(!tdBlocked(M,nx,ny,false)){C.x=nx;C.y=ny;C.fr+=sp;C.dir=Math.abs(dx)>Math.abs(dy)?(dx<0?'l':'r'):(dy<0?'u':'d')}else C.path=null}
 const dist=Math.hypot(C.x-p.x,C.y-p.y);
 if(C.mode==='run'){if(dist<11)return chaseEnd(false);if(p.x>TX(50)&&Math.abs(p.y-TX(20))<TX(3))return chaseEnd(true);if(C.t>C.dur)return chaseEnd(true)}
 else{if(dist<13)return chaseEnd(true);if(C.t>C.dur)return chaseEnd(false)}}
function chaseEnd(win){const C=TDP.chase;C.done=true;const v=dpV();const t=tdS();t.f.chases=(t.f.chases||0)+1;if(win)t.f.chaseWins=(t.f.chaseWins||0)+1;save();apply({aff:2,energy:-8});
 const L=C.mode==='run'?(win?(v?[['','You make the torii with her footsteps three trees behind you. She arrives, furious, and hits you in the arm.'],['hitmeuppp','u CHEATED. u have LONG LEGS. that’s CHEATING.'],['K9','I have had them the whole time.']]:[['','You burst through the torii with him a full tree behind. You turn round with both arms up like you just won the 400.'],['hitmeuppp','FORTY NINE POINT EIGHT. baby.'],['K9','...I let you win.'],['hitmeuppp','u did NOT. u were breathing like a dog in a car.']])
  :(v?[['','She catches you by the coat. For somebody so small she tackles like a truck. You both go down in the pine needles.'],['hitmeuppp','gotcha. GOTCHA. say it. say i got you.'],['K9','You got me.']]:[['','An arm round your waist, and the world tips, and you’re both in the leaves, laughing, his coat full of pine needles.'],['K9','Caught.'],['hitmeuppp','...ok. ok yeah. caught. don’t get up yet.']]))
  :(win?(v?[['','You catch her at the edge of the clearing. She goes completely limp, and you’d honestly have preferred a fight.'],['hitmeuppp','u have to carry me now. those are the rules.'],['K9','Those are not the rules.'],['','He carries her back to the tunnel.']]:[['','You catch him by the back of the coat and he stops dead, so suddenly you run into him.'],['K9','You caught me.'],['hitmeuppp','u stopped on PURPOSE.'],['K9','I would never.']])
  :(v?[['','She’s gone. Just gone, into the trees, like she was never there. Then, from somewhere above you:'],['hitmeuppp','up here, grandpa.'],['','She is in a tree. You have no idea how she got into the tree.']]:[['','He’s gone. A man that size, gone, into a forest, without a sound. Then a hand on your shoulder from behind.'],['K9','Boo.'],['hitmeuppp','I HATE YOU. i hate u so much. do it again.']]));
 tdSay(L,()=>{TDP.chase=null})}
function chasePost(sc){const C=TDP.chase;if(!C)return;const p=sc.p,cam=sc.cam;
 if(!C.done){const sx=C.x-cam.x,sy=C.y-cam.y;c.save();c.translate(-cam.x,-cam.y);tdActor(C.o,C.x,C.y,C.dir,true,C.fr,{});c.restore();
  const left=Math.max(0,Math.ceil((C.dur-C.t)/60));rect(W-96,H/2-30,88,16,'rgba(10,8,14,.85)');txt((C.mode==='run'?'RUN · ':'HUNT · ')+left+'s',W-52,H/2-18,C.mode==='run'?'#ff8ab0':'#5fd4c4',10,'center');
  rect(W-96,H/2-12,88,4,'#2e2638');rect(W-96,H/2-12,88*C.stam/100,4,C.stam>25?'#7fe08a':'#ff6a6a');txt('SHIFT · sprint',W-52,H/2,'#8a8296',5,'center');
  if(sx<0||sx>W||sy<14||sy>H){const a=Math.atan2(sy-H/2,sx-W/2);const ex=W/2+Math.cos(a)*120,ey=H/2+Math.sin(a)*70;c.fillStyle=C.mode==='run'?'#ff6a6a':'#5fd4c4';c.beginPath();c.arc(ex,ey,4,0,7);c.fill()}}}
